	_update_summary()


func _on_start_button_pressed() -> void:
	print("Partita avviata per: ", name_input.text.strip_edges())
	print("Livello difficoltà scelto: ", difficulty_slider.value)
	print("Potenziamenti abilitati: ", powerups_check.button_pressed)


func _update_summary() -> void:
	var player_name: String = name_input.text.strip_edges()
	if player_name == "":
		player_name = "(nessun nome)"

	var bonus_status: String = "No"
	if powerups_check.button_pressed:
		bonus_status = "Sì"

	var diff_level: int = int(difficulty_slider.value)
	summary_label.text = "Profilo: " + player_name + " | Difficoltà: " + str(diff_level) + " | Rubini: " + bonus_status
